53	const PROCESSING_FEE = 5;
54	const FIRST_INSURANCE_RATE = 0.1;
55	
56	const BASE_PREMIUMS: Record<string, number> = {
57	  sword: 100,
58	  amulet: 60,
59	  staff: 80,
60	  potion: 40,
61	  rune: 25,
62	  moonstone: 25,
63	};
64	
65	const COMPONENT_TYPES = new Set(["rune", "moonstone"]);
66	const COMPONENT_BLOCK_SIZE = 3;
67	const COMPONENT_BLOCK_PREMIUM = 60;
68	
69	const roundUpInMHPCOsFavor = Math.ceil;
70	
71	const basePremiumFor = (type: string, count: number): number => {
72	  const isComponentBlock =
73	    COMPONENT_TYPES.has(type) && count === COMPONENT_BLOCK_SIZE;
74	  return isComponentBlock
75	    ? COMPONENT_BLOCK_PREMIUM
76	    : count * BASE_PREMIUMS[type];
77	};
78	
79	const countItemsByType = (items: QuoteItem[]): Map<string, number> => {
80	  const countsByType = new Map<string, number>();
81	  for (const item of items) {
82	    countsByType.set(item.type, (countsByType.get(item.type) ?? 0) + 1);
83	  }
84	  return countsByType;
85	};
86	
87	const quotePremium = (items: QuoteItem[]): number => {
88	  let basePremium = 0;
89	  for (const [type, count] of countItemsByType(items)) {
90	    basePremium += basePremiumFor(type, count);
91	  }
92	  const firstInsuranceSurcharge = basePremium * FIRST_INSURANCE_RATE;
93	  return roundUpInMHPCOsFavor(
94	    basePremium + firstInsuranceSurcharge + PROCESSING_FEE,
95	  );
96	};
97	
98	export const runScenario = (scenario: Scenario): ScenarioOutput => {
99	  const quoteStep = scenario.steps[0] as QuoteStep;
100	  return { results: [{ premium: quotePremium(quoteStep.items) }] };
101	};
